Index: design/html/components.css
===================================================================
--- design/html/components.css	
+++ design/html/components.css	
@@ -0,0 +1,245 @@
+/* ===== Buttons ===== */
+.pathland-button {
+  display: inline-flex; align-items: center; justify-content: center;
+  border-radius: var(--pl-button-radius);
+  background-color: var(--pl-button-background);
+  padding: var(--pl-button-padding-vertical) var(--pl-button-padding-horizontal);
+  font-size: var(--pl-button-font-size); font-weight: var(--pl-button-font-weight); line-height: var(--pl-button-line-height);
+  color: var(--pl-button-foreground);
+  box-shadow: inset 0 0 0 var(--pl-button-border-width) var(--pl-button-border),
+    var(--pl-elevation-low-x) var(--pl-elevation-low-y) var(--pl-elevation-low-blur) var(--pl-elevation-low-radius) var(--pl-elevation-low-color);
+  transition: background-color var(--pl-button-transition-duration), box-shadow var(--pl-button-transition-duration);
+}
+.pathland-button:hover { background-color: var(--pl-button-background-hover); }
+.pathland-button:focus-visible { outline: var(--pl-button-focus-ring-width) solid var(--pl-button-focus-ring-color); outline-offset: var(--pl-button-focus-ring-offset); }
+.pathland-button:disabled { opacity: var(--pl-opacity-disabled); pointer-events: none; }
+/* Semantic icons (ICON): the inline SVG is sized like text — `1em` follows the
+   resolved font-size (FONT_SIZE on the node, else the inherited/default size)
+   and `currentColor` follows COLOR. */
+.pathland-icon {
+  display: inline-block;
+  width: var(--pl-icon-size); height: var(--pl-icon-size);
+  min-width: var(--pl-icon-size); min-height: var(--pl-icon-size);
+  vertical-align: var(--pl-icon-offset);
+  flex: none;
+}
+.pathland-icon path, .pathland-icon circle, .pathland-icon rect, .pathland-icon line,
+.pathland-icon polyline, .pathland-icon polygon {
+  shape-rendering: geometricPrecision;
+}
+
+/* ===== Toggle switch / checkbox ===== */
+.pathland-toggle { display: inline-flex; align-items: center; gap: var(--pl-toggle-gap); }
+.pathland-toggle input[type='checkbox'] { accent-color: var(--pl-toggle-accent); width: var(--pl-toggle-checkbox-size); height: var(--pl-toggle-checkbox-size); }
+.pathland-toggle input[role='switch'] {
+  appearance: none; width: var(--pl-toggle-switch-width); height: var(--pl-toggle-switch-height); border-radius: var(--pl-toggle-switch-radius);
+  background-color: var(--pl-toggle-track-off); cursor: pointer; position: relative;
+  transition: background-color var(--pl-toggle-transition-duration); flex: none;
+}
+.pathland-toggle input[role='switch']:checked { background-color: var(--pl-toggle-track-on); }
+.pathland-toggle input[role='switch']::after {
+  content: ''; position: absolute; top: var(--pl-toggle-thumb-offset); left: var(--pl-toggle-thumb-offset);
+  width: var(--pl-toggle-thumb-size); height: var(--pl-toggle-thumb-size); border-radius: var(--pl-toggle-switch-radius); background: var(--pl-toggle-thumb);
+  transition: left var(--pl-toggle-transition-duration);
+}
+.pathland-toggle input[role='switch']:checked::after { left: var(--pl-toggle-thumb-travel); }
+.pathland-toggle input[role='switch']:focus-visible { outline: var(--pl-toggle-focus-ring-width) solid var(--pl-toggle-accent); outline-offset: var(--pl-toggle-focus-ring-offset); }
+
+/* ===== Slider =====
+   A renderer-owned range: the native input stays for keyboard/pointer
+   interaction and accessibility, but its track, fill, and thumb are drawn from
+   design tokens (`slider.track`, `slider.accent`, `slider.thumb`). The fill
+   custom property is set inline by SSR and kept in sync by the DOM client. */
+.pathland-slider { display: inline-flex; align-items: center; gap: var(--pl-slider-gap); }
+.pathland-slider input[type='range'] {
+  -webkit-appearance: none;
+  appearance: none;
+  flex: 1;
+  min-width: 0;
+  height: var(--pl-slider-height);
+  margin: 0;
+  background: transparent;
+  cursor: pointer;
+  accent-color: var(--pl-slider-accent);
+  --pl-slider-fill: 0%;
+}
+.pathland-slider input[type='range']::-webkit-slider-runnable-track {
+  height: var(--pl-slider-track-height);
+  border-radius: var(--pl-slider-track-radius);
+  background: linear-gradient(
+    to right,
+    var(--pl-slider-accent) 0%,
+    var(--pl-slider-accent) var(--pl-slider-fill),
+    var(--pl-slider-track) var(--pl-slider-fill),
+    var(--pl-slider-track) 100%
+  );
+}
+.pathland-slider input[type='range']::-webkit-slider-thumb {
+  -webkit-appearance: none;
+  appearance: none;
+  width: var(--pl-slider-thumb-size);
+  height: var(--pl-slider-thumb-size);
+  margin-top: var(--pl-slider-thumb-offset);
+  border: var(--pl-slider-thumb-border-width) solid var(--pl-slider-track);
+  border-radius: var(--pl-slider-track-radius);
+  background: var(--pl-slider-thumb);
+  box-shadow: var(--pl-elevation-low-x) var(--pl-elevation-low-y)
+    var(--pl-elevation-low-blur) var(--pl-elevation-low-radius)
+    var(--pl-elevation-low-color);
+}
+.pathland-slider input[type='range']::-moz-range-track {
+  height: var(--pl-slider-track-height);
+  border-radius: var(--pl-slider-track-radius);
+  background: var(--pl-slider-track);
+}
+.pathland-slider input[type='range']::-moz-range-progress {
+  height: var(--pl-slider-track-height);
+  border-radius: var(--pl-slider-track-radius);
+  background: var(--pl-slider-accent);
+}
+.pathland-slider input[type='range']::-moz-range-thumb {
+  width: var(--pl-slider-thumb-size);
+  height: var(--pl-slider-thumb-size);
+  border: var(--pl-slider-thumb-border-width) solid var(--pl-slider-track);
+  border-radius: var(--pl-slider-track-radius);
+  background: var(--pl-slider-thumb);
+  box-shadow: var(--pl-elevation-low-x) var(--pl-elevation-low-y)
+    var(--pl-elevation-low-blur) var(--pl-elevation-low-radius)
+    var(--pl-elevation-low-color);
+}
+.pathland-slider input[type='range']:focus-visible {
+  outline: var(--pl-slider-focus-ring-width) solid var(--pl-slider-accent);
+  outline-offset: var(--pl-slider-focus-ring-offset);
+  border-radius: var(--pl-slider-track-radius);
+}
+.pathland-slider input[type='range']:disabled {
+  cursor: default;
+  opacity: var(--pl-opacity-disabled);
+}
+
+/* ===== Media (custom AudioStyle/VideoStyle) ===== */
+/* A media node with custom control children wraps a bare (control-less) media
+   element; the element is the app-driven playback sink, so it stays hidden and
+   only the custom control children are visible. Native media (no children)
+   keep their own `controls` and are not wrapped. */
+.pathland-media audio,
+.pathland-media video { display: none; }
+
+/* ===== Native controls (inherit Tailwind-derived preflight + tokens) ===== */
+/* Every native form control shares the design-system surface: the Tailwind
+   preflight supplies the font/color reset, these tokens supply the visual base.
+   App-authored inline properties (WIDTH/HEIGHT/PADDING/COLOR/…) still win. */
+.pathland-control,
+.pathland-input {
+  border-radius: var(--pl-input-radius);
+  background-color: var(--pl-input-background);
+  font-family: inherit;
+  font-size: var(--pl-input-font-size);
+  line-height: var(--pl-control-line-height);
+  color: var(--pl-input-foreground);
+  outline: var(--pl-control-border-width) solid var(--pl-input-border);
+  outline-offset: calc(-1 * var(--pl-control-border-width));
+  transition: outline-color var(--pl-control-transition-duration), box-shadow var(--pl-control-transition-duration);
+  accent-color: var(--pl-control-accent);
+  color-scheme: inherit;
+}
+.pathland-control {
+  min-height: var(--pl-control-height);
+  padding: var(--pl-control-padding-vertical) var(--pl-control-padding-horizontal);
+}
+.pathland-input {
+  display: block;
+  width: 100%;
+  flex: 1 1 auto;
+  min-width: 0;
+  padding: var(--pl-input-padding-vertical) var(--pl-input-padding-horizontal);
+}
+.pathland-input::placeholder,
+.pathland-control::placeholder { color: var(--pl-input-placeholder); }
+.pathland-input:focus,
+.pathland-control:focus {
+  outline: var(--pl-input-focus-ring-width) solid var(--pl-input-focus);
+  outline-offset: var(--pl-input-focus-ring-offset);
+}
+.pathland-control:disabled { opacity: var(--pl-opacity-disabled); }
+
+/* PICKER: keep the native dropdown affordance; theme the field + options. */
+.pathland-select { display: inline-block; cursor: pointer; }
+.pathland-select option {
+  background-color: var(--pl-input-background);
+  color: var(--pl-input-foreground);
+}
+
+/* DATE_PICKER / COLOR_PICKER: the popup itself is UA-owned; the field surface,
+   scheme, and picker highlights follow the design system. */
+.pathland-date,
+.pathland-color { display: inline-flex; align-items: center; }
+.pathland-color { padding: var(--pl-control-padding-vertical); }
+.pathland-color::-webkit-color-swatch-wrapper { padding: 0; }
+.pathland-color::-webkit-color-swatch {
+  border: 0;
+  border-radius: calc(var(--pl-input-radius) - var(--pl-input-swatch-inset));
+}
+
+/* PROGRESS_VIEW: tokenized track/fill across engines. */
+.pathland-progress {
+  appearance: none;
+  -webkit-appearance: none;
+  display: block;
+  width: 100%;
+  height: var(--pl-progress-height);
+  border: 0;
+  border-radius: var(--pl-progress-radius);
+  overflow: hidden;
+  background-color: var(--pl-progress-track);
+  color: var(--pl-progress-fill);
+  accent-color: var(--pl-progress-fill);
+}
+.pathland-progress::-webkit-progress-bar {
+  background-color: var(--pl-progress-track);
+  border-radius: var(--pl-progress-radius);
+}
+.pathland-progress::-webkit-progress-value {
+  background-color: var(--pl-progress-fill);
+  border-radius: var(--pl-progress-radius);
+}
+.pathland-progress::-moz-progress-bar {
+  background-color: var(--pl-progress-fill);
+  border-radius: var(--pl-progress-radius);
+}
+
+/* VIDEO: native controls are UA shadow DOM (best-effort scheme/accent only);
+   app-driven media (`.pathland-media` + custom controls) is fully themeable. */
+.pathland-video,
+.pathland-media {
+  max-width: 100%;
+  background-color: var(--pl-color-surface);
+  color: var(--pl-color-text-primary);
+  border-radius: var(--pl-control-radius);
+  accent-color: var(--pl-control-accent);
+  color-scheme: inherit;
+}
+
+/* ===== Stepper ===== */
+.pathland-stepper { display: inline-flex; align-items: center; gap: var(--pl-stepper-gap); }
+.pathland-stepper button { width: var(--pl-stepper-button-size); height: var(--pl-stepper-button-size); border-radius: var(--pl-stepper-radius); border: var(--pl-stepper-border-width) solid var(--pl-stepper-border); background: var(--pl-stepper-background); color: var(--pl-stepper-accent); }
+
+/* ===== Progress / gauge / spinner ===== */
+.pathland-spinner {
+  width: var(--pl-spinner-size); height: var(--pl-spinner-size); border: var(--pl-spinner-border-width) solid var(--pl-progress-track);
+  border-top-color: var(--pl-progress-fill); border-radius: var(--pl-radius-full);
+  animation: pathland-spin var(--pl-spinner-duration) linear infinite;
+}
+@keyframes pathland-spin { to { transform: rotate(360deg); } }
+.pathland-gauge { display: block; height: var(--pl-gauge-height); width: 100%; background: var(--pl-gauge-track); border-radius: var(--pl-gauge-radius); overflow: hidden; }
+.pathland-gauge > div { height: 100%; background: var(--pl-gauge-fill); transition: width var(--pl-gauge-transition-duration); }
+
+/* ===== Menu (popover) ===== */
+.pathland-menu { position: relative; display: inline-block; }
+.pathland-menu-items {
+  display: none; position: absolute; min-width: var(--pl-menu-min-width); background: var(--pl-menu-background);
+  color: var(--pl-menu-foreground); border: var(--pl-menu-border-width) solid var(--pl-menu-border); border-radius: var(--pl-menu-radius);
+  box-shadow: var(--pl-elevation-high-x) var(--pl-elevation-high-y) var(--pl-elevation-high-blur) var(--pl-elevation-high-radius) var(--pl-elevation-high-color);
+  z-index: var(--pl-menu-z-index);
+}
+.pathland-menu:hover .pathland-menu-items { display: block; }

Index: design/html/reset.css
===================================================================
--- design/html/reset.css	
+++ design/html/reset.css	
@@ -0,0 +1,44 @@
+/* ===== Preflight reset (vendored from Tailwind CSS, MIT — see THIRD_PARTY_NOTICES) ===== */
+*, ::before, ::after { box-sizing: border-box; border-width: 0; border-style: solid; border-color: currentColor; }
+::before, ::after { --tw-content: ''; }
+html { line-height: 1.5; -webkit-text-size-adjust: 100%; -moz-tab-size: 4; tab-size: 4; font-family: var(--pl-font-sans); font-feature-settings: 'liga' 1, 'calt' 1; color-scheme: light dark; background-color: var(--pl-color-background); color: var(--pl-color-text-primary); }
+body { margin: 0; line-height: inherit; }
+hr { height: 0; color: inherit; border-top-width: 1px; }
+abbr:where([title]) { text-decoration: underline dotted; }
+h1, h2, h3, h4, h5, h6 { font-size: inherit; font-weight: inherit; }
+a { color: inherit; text-decoration: inherit; }
+b, strong { font-weight: bolder; }
+code, kbd, samp, pre { font-family: ui-monospace, SFMono-Regular, Menlo, monospace; font-size: 1em; }
+small { font-size: 80%; }
+sub, sup { font-size: 75%; line-height: 0; position: relative; vertical-align: baseline; }
+sub { bottom: -0.25em; } sup { top: -0.5em; }
+table { text-indent: 0; border-color: inherit; border-collapse: collapse; }
+button, input, optgroup, select, textarea { font-family: inherit; font-feature-settings: inherit; font-variation-settings: inherit; font-size: 100%; font-weight: inherit; line-height: inherit; letter-spacing: inherit; color: inherit; margin: 0; padding: 0; }
+progress, video { font: inherit; color: inherit; }
+button, select { text-transform: none; }
+button, [type='button'], [type='reset'], [type='submit'] { -webkit-appearance: button; background-color: transparent; background-image: none; }
+:-moz-focusring { outline: auto; }
+:-moz-ui-invalid { box-shadow: none; }
+progress { vertical-align: baseline; }
+::-webkit-inner-spin-button, ::-webkit-outer-spin-button { height: auto; }
+[type='search'] { -webkit-appearance: textfield; outline-offset: -2px; }
+::-webkit-search-decoration { -webkit-appearance: none; }
+::-webkit-file-upload-button { -webkit-appearance: button; font: inherit; }
+summary { display: list-item; }
+blockquote, dl, dd, h1, h2, h3, h4, h5, h6, hr, figure, p, pre { margin: 0; }
+fieldset { margin: 0; padding: 0; }
+legend { padding: 0; }
+ol, ul, menu { list-style: none; margin: 0; padding: 0; }
+textarea { resize: vertical; }
+input::placeholder, textarea::placeholder { opacity: 1; color: var(--pl-color-text-secondary); }
+button, [role='button'] { cursor: pointer; }
+:disabled { cursor: default; }
+img, svg, video, canvas, audio, iframe, embed, object { display: block; vertical-align: middle; }
+img, video { max-width: 100%; height: auto; }
+[hidden] { display: none; }
+
+/* ===== Adjust body ===== */
+body {
+  display: flex;
+  height: 100vh;
+}

Index: design/scripts/build.mjs
===================================================================
--- design/scripts/build.mjs	
+++ design/scripts/build.mjs	
@@ -0,0 +1,61 @@
+// Build the built-in HTML base design:
+//   Style Dictionary → design/build/{tokens.css,manifest.json}
+//   reset.css + tokens.css + components.css → design/build/base.css
+//
+// `base.css` is the bundle the Rust renderer embeds (synced to
+// lib/rust/crates/pathland-render-html/assets/base.css).
+
+import { mkdir, readFile, writeFile } from "node:fs/promises";
+import { join } from "node:path";
+import { pathToFileURL } from "node:url";
+import StyleDictionary from "style-dictionary";
+import config from "../style-dictionary.config.mjs";
+import { DESIGN_ROOT } from "./token-model.mjs";
+
+const BUILD = join(DESIGN_ROOT, "build");
+
+const BANNER = `/* Pathland HTML base design — generated by \`npm --prefix design run build\`. */
+/* Edit design/tokens/** or design/html/{reset,components}.css, not this file. */
+`;
+
+async function readDesignFile(name) {
+  return readFile(join(DESIGN_ROOT, name), "utf8");
+}
+
+export async function buildDesign() {
+  await mkdir(BUILD, { recursive: true });
+  const dictionary = new StyleDictionary(config);
+  await dictionary.buildAllPlatforms();
+
+  const [reset, tokens, components] = await Promise.all([
+    readDesignFile("html/reset.css"),
+    readFile(join(BUILD, "tokens.css"), "utf8"),
+    readDesignFile("html/components.css"),
+  ]);
+
+  const base = [
+    BANNER,
+    reset.trim(),
+    "",
+    tokens.trim(),
+    "",
+    components.trim(),
+    "",
+  ].join("\n");
+
+  const basePath = join(BUILD, "base.css");
+  await writeFile(basePath, base, "utf8");
+  return basePath;
+}
+
+if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
+  buildDesign()
+    .then((basePath) => {
+      console.log(`design: wrote ${basePath}`);
+      console.log("design: wrote build/tokens.css and build/manifest.json");
+    })
+    .catch((error) => {
+      console.error(error);
+      process.exitCode = 1;
+    });
+}

Index: design/scripts/check.mjs
===================================================================
--- design/scripts/check.mjs	
+++ design/scripts/check.mjs	
@@ -0,0 +1,298 @@
+// Validate the built-in HTML base design:
+//   - every Tier-1 protocol catalog token is present;
+//   - base → semantic → component layer/reference rules hold;
+//   - every emitted token has light, platform-dark, forced-dark-scheme and
+//     forced-dark variable values;
+//   - every `$type: dimension` token is recognized by the canonical
+//     `isLengthToken` rules in pathland-render-html::token_spec;
+//   - internal tokens are marked;
+//   - no references are unresolved;
+//   - the generated build/ files match the current token sources.
+
+import { readFile } from "node:fs/promises";
+import { join } from "node:path";
+import {
+  DESIGN_ROOT,
+  baseTokens,
+  cssValueFor,
+  emittedTokens,
+  loadTokens,
+  manifestEntries,
+  refTarget,
+  tokenToCssVar,
+  tokenToForcedDarkCssVar,
+} from "./token-model.mjs";
+
+const RUST_ROOT = join(DESIGN_ROOT, "..", "lib", "rust");
+
+const failures = [];
+function fail(message) {
+  failures.push(message);
+}
+
+/** Read a `pub const NAME: &[...] = &[ ... ];` block from the Rust token spec. */
+function rustBlock(source, name) {
+  const re = new RegExp(
+    `pub const ${name}\\s*:\\s*&\\[[^=]*=\\s*&\\[([\\s\\S]*?)\\];`,
+  );
+  const match = re.exec(source);
+  if (!match) throw new Error(`could not find ${name} in token_spec.rs`);
+  return match[1];
+}
+
+function strings(block) {
+  return [...block.matchAll(/"([^"]*)"/g)].map((match) => match[1]);
+}
+
+function pairs(block) {
+  return [...block.matchAll(/\(\s*"([^"]*)"\s*,\s*"([^"]*)"\s*\)/g)].map(
+    (match) => [match[1], match[2]],
+  );
+}
+
+async function lengthRules() {
+  const source = await readFile(join(RUST_ROOT, "crates", "pathland-render-html", "src", "token_spec.rs"), "utf8");
+  return {
+    prefixes: strings(rustBlock(source, "LENGTH_PREFIXES")),
+    prefixSuffix: pairs(rustBlock(source, "LENGTH_PREFIX_SUFFIX")),
+    exact: strings(rustBlock(source, "LENGTH_EXACT")),
+    elevationSuffixes: strings(rustBlock(source, "LENGTH_ELEVATION_SUFFIXES")),
+  };
+}
+
+function isLengthToken(path, rules) {
+  if (rules.prefixes.some((prefix) => path.startsWith(prefix))) return true;
+  if (
+    rules.prefixSuffix.some(
+      ([prefix, suffix]) => path.startsWith(prefix) && path.endsWith(suffix),
+    )
+  ) {
+    return true;
+  }
+  if (rules.exact.includes(path)) return true;
+  return (
+    path.startsWith("elevation.") &&
+    rules.elevationSuffixes.some((suffix) => path.endsWith(suffix))
+  );
+}
+
+async function tier1Catalog() {
+  const source = await readFile(join(RUST_ROOT, "crates", "pathland-core", "src", "tokens.rs"), "utf8");
+  return strings(rustBlock(source, "TIER1_TOKENS"));
+}
+
+const COMPONENT_BASE_SCALE = [
+  "base.space.",
+  "base.radius.",
+  "base.border.width.",
+  "base.size.",
+  "base.font.",
+  "base.duration.",
+  "base.z.",
+];
+
+function count(haystack, needle) {
+  return haystack.split(needle).length - 1;
+}
+
+function checkReference(owner, value, tokens) {
+  const target = refTarget(value);
+  if (!target) {
+    fail(`${owner}: emitted tokens must reference another token (got literal ${JSON.stringify(value)})`);
+    return null;
+  }
+  const targetToken = tokens.get(target);
+  if (!targetToken) {
+    fail(`${owner}: unresolved reference {${target}}`);
+    return null;
+  }
+  return targetToken;
+}
+
+function allowedTarget(owner, targetToken, token) {
+  if (targetToken.layer === "base") {
+    if (token.layer === "semantic") return;
+    if (token.layer === "component") {
+      const scale = COMPONENT_BASE_SCALE.some((prefix) => targetToken.path.startsWith(prefix));
+      const justified =
+        typeof token.extensions.baseReference === "string" &&
+        token.extensions.baseReference.trim().length > 0;
+      if (scale || justified) return;
+      fail(
+        `${owner}: component → base reference {${targetToken.path}} needs a scale path or ` +
+          `$extensions.pathland.baseReference justification`,
+      );
+      return;
+    }
+  }
+  if (token.layer === "semantic") {
+    const alias =
+      typeof token.extensions.semanticAlias === "string" &&
+      token.extensions.semanticAlias.trim().length > 0;
+    if (targetToken.layer === "semantic" && alias) return;
+    fail(
+      `${owner}: semantic tokens must reference base tokens ` +
+        `(or a semantic alias with $extensions.pathland.semanticAlias), not ` +
+        `${targetToken.layer} ${targetToken.path}`,
+    );
+    return;
+  }
+  if (token.layer === "component" && targetToken.layer === "semantic") return;
+  fail(`${owner}: component tokens must reference semantic tokens, not ${targetToken.layer} ${targetToken.path}`);
+}
+
+const tokens = loadTokens(join(DESIGN_ROOT));
+const emitted = emittedTokens(tokens);
+const base = baseTokens(tokens);
+const byPath = new Map(emitted.map((token) => [token.path, token]));
+
+// --- Layer / reference rules -------------------------------------------------
+for (const token of base) {
+  if (refTarget(token.value)) {
+    fail(`${token.path}: base tokens are literals and must not reference other tokens`);
+  }
+  if (token.dark !== undefined) {
+    fail(`${token.path}: base tokens have no dark extension (they are internal literals)`);
+  }
+}
+
+for (const token of emitted) {
+  const target = checkReference(token.path, token.value, tokens);
+  if (target) allowedTarget(token.path, target, token);
+  if (token.dark !== undefined) {
+    const darkTarget = checkReference(`${token.path} (dark)`, token.dark, tokens);
+    if (darkTarget) allowedTarget(`${token.path} (dark)`, darkTarget, token);
+  }
+}
+
+// --- Catalog coverage --------------------------------------------------------
+const catalog = await tier1Catalog();
+for (const path of catalog) {
+  if (!byPath.has(path)) fail(`missing Tier-1 catalog token ${path}`);
+}
+
+// --- Dark / forced-dark values ----------------------------------------------
+for (const token of emitted) {
+  for (const layer of ["light", "dark", "forced-dark"]) {
+    try {
+      const value = cssValueFor(token, layer, tokens);
+      if (!value) fail(`${token.path}: empty ${layer} value`);
+    } catch (error) {
+      fail(`${token.path}: ${error.message}`);
+    }
+  }
+}
+
+// --- CSS variable references -------------------------------------------------
+const emittedCssVars = new Set(emitted.map((token) => tokenToCssVar(token.path)));
+const localCssVars = new Set(["--pl-slider-fill"]);
+for (const file of ["html/reset.css", "html/components.css"]) {
+  const css = await readFile(join(DESIGN_ROOT, file), "utf8");
+  for (const match of css.matchAll(/var\((--pl-[A-Za-z0-9_-]+)/g)) {
+    const name = match[1];
+    if (!emittedCssVars.has(name) && !localCssVars.has(name)) {
+      fail(`${file}: unresolved CSS variable ${name}`);
+    }
+  }
+}
+
+// --- Dimension / length conventions -----------------------------------------
+const rules = await lengthRules();
+for (const token of emitted) {
+  if (token.type === "dimension" && !isLengthToken(token.path, rules)) {
+    fail(
+      `${token.path}: $type dimension is not recognized by token_spec::isLengthToken ` +
+        `(add a length rule to lib/rust/crates/pathland-render-html/src/token_spec.rs)`,
+    );
+  }
+}
+
+// --- Internal tokens ---------------------------------------------------------
+for (const token of emitted) {
+  if (token.extensions.internal !== undefined && typeof token.extensions.internal !== "boolean") {
+    fail(`${token.path}: $extensions.pathland.internal must be a boolean`);
+  }
+  if (token.type === "duration" && token.extensions.internal !== true) {
+    fail(`${token.path}: duration tokens are renderer-internal and must be marked internal`);
+  }
+  if (
+    ["menu.z-index", "icon.size", "icon.offset"].includes(token.path) &&
+    token.extensions.internal !== true
+  ) {
+    fail(`${token.path}: internal token must be marked $extensions.pathland.internal`);
+  }
+}
+
+// --- Generated build consistency --------------------------------------------
+let manifest;
+try {
+  manifest = JSON.parse(await readFile(join(DESIGN_ROOT, "build", "manifest.json"), "utf8"));
+} catch {
+  fail("build/manifest.json is missing — run `npm --prefix design run build` first");
+}
+
+let tokensCss = "";
+try {
+  tokensCss = await readFile(join(DESIGN_ROOT, "build", "tokens.css"), "utf8");
+} catch {
+  fail("build/tokens.css is missing — run `npm --prefix design run build` first");
+}
+
+if (manifest) {
+  const expected = manifestEntries(tokens);
+  if (JSON.stringify(manifest) !== JSON.stringify(expected)) {
+    fail("build/manifest.json is stale — run `npm --prefix design run build`");
+  }
+  const emittedPaths = new Set(manifest.map((entry) => entry.path));
+  for (const token of emitted) {
+    if (!emittedPaths.has(token.path)) fail(`${token.path}: missing from the manifest`);
+  }
+  for (const entry of manifest) {
+    if (!entry.darkCssVar) fail(`${entry.path}: manifest has no darkCssVar`);
+    if (!entry.cssVar.startsWith("--pl-")) fail(`${entry.path}: manifest cssVar must start with --pl-`);
+  }
+}
+
+if (tokensCss) {
+  for (const needle of [
+    ":root {",
+    "@media (prefers-color-scheme: dark) {",
+    ":root:not([data-pathland-scheme]) {",
+    ":root[data-pathland-scheme='dark'] {",
+    "  color-scheme: dark;",
+    ":root[data-pathland-scheme='light'] {",
+    "  color-scheme: light;",
+    "Forced-dark values",
+  ]) {
+    if (!tokensCss.includes(needle)) fail(`build/tokens.css is missing the ${needle} layer`);
+  }
+  for (const token of emitted) {
+    const cssVar = tokenToCssVar(token.path);
+    const darkVar = tokenToForcedDarkCssVar(token.path);
+    if (count(tokensCss, `${cssVar}:`) !== 3) {
+      fail(
+        `${token.path}: expected 3 light/dark declarations for ${cssVar} ` +
+          `(root + platform-dark + forced-dark scheme), found ${count(tokensCss, `${cssVar}:`)}`,
+      );
+    }
+    if (count(tokensCss, `${darkVar}:`) !== 1) {
+      fail(`${token.path}: expected exactly one forced-dark declaration for ${darkVar}`);
+    }
+  }
+  for (const token of base) {
+    const cssVar = tokenToCssVar(token.path);
+    if (tokensCss.includes(`${cssVar}:`)) {
+      fail(`${token.path}: base tokens must not be emitted into tokens.css`);
+    }
+  }
+}
+
+if (failures.length > 0) {
+  for (const message of failures) console.error(`design check: ${message}`);
+  console.error(`design check: ${failures.length} problem(s)`);
+  process.exit(1);
+}
+
+console.log(
+  `design check: ok — ${emitted.length} emitted tokens, ${catalog.length} Tier-1 catalog tokens, ${base.length} base tokens`,
+);

