    case VAL_F32:
      return String(f32FromBits(c));
    case VAL_I32:
      return String(c | 0);
    case VAL_U32:
      return String(c >>> 0);
    case VAL_U8:
      return String(c & 0xff);
    default:
      return String(c >>> 0);
