/* ===== Buttons ===== */
.pathland-button {
  display: inline-flex; align-items: center; justify-content: center;
  border-radius: var(--pl-button-radius);
  background-color: var(--pl-button-background);
  padding: var(--pl-button-padding-vertical) var(--pl-button-padding-horizontal);
  font-size: var(--pl-button-font-size); font-weight: var(--pl-button-font-weight); line-height: var(--pl-button-line-height);
  color: var(--pl-button-foreground);
  box-shadow: inset 0 0 0 var(--pl-button-border-width) var(--pl-button-border),
    var(--pl-elevation-low-x) var(--pl-elevation-low-y) var(--pl-elevation-low-blur) var(--pl-elevation-low-radius) var(--pl-elevation-low-color);
  transition: background-color var(--pl-button-transition-duration), box-shadow var(--pl-button-transition-duration);
}
.pathland-button:hover { background-color: var(--pl-button-background-hover); }
.pathland-button:focus-visible { outline: var(--pl-button-focus-ring-width) solid var(--pl-button-focus-ring-color); outline-offset: var(--pl-button-focus-ring-offset); }
.pathland-button:disabled { opacity: var(--pl-opacity-disabled); pointer-events: none; }
/* Semantic icons (ICON): the inline SVG is sized like text — `1em` follows the
   resolved font-size (FONT_SIZE on the node, else the inherited/default size)
   and `currentColor` follows COLOR. */
.pathland-icon {
  display: inline-block;
  width: var(--pl-icon-size); height: var(--pl-icon-size);
  min-width: var(--pl-icon-size); min-height: var(--pl-icon-size);
  vertical-align: var(--pl-icon-offset);
  flex: none;
}
.pathland-icon path, .pathland-icon circle, .pathland-icon rect, .pathland-icon line,
.pathland-icon polyline, .pathland-icon polygon {
  shape-rendering: geometricPrecision;
}

/* ===== Toggle switch / checkbox ===== */
.pathland-toggle { display: inline-flex; align-items: center; gap: var(--pl-toggle-gap); }
.pathland-toggle input[type='checkbox'] { accent-color: var(--pl-toggle-accent); width: var(--pl-toggle-checkbox-size); height: var(--pl-toggle-checkbox-size); }
.pathland-toggle input[role='switch'] {
  appearance: none; width: var(--pl-toggle-switch-width); height: var(--pl-toggle-switch-height); border-radius: var(--pl-toggle-switch-radius);
  background-color: var(--pl-toggle-track-off); cursor: pointer; position: relative;
  transition: background-color var(--pl-toggle-transition-duration); flex: none;
}
.pathland-toggle input[role='switch']:checked { background-color: var(--pl-toggle-track-on); }
.pathland-toggle input[role='switch']::after {
  content: ''; position: absolute; top: var(--pl-toggle-thumb-offset); left: var(--pl-toggle-thumb-offset);
  width: var(--pl-toggle-thumb-size); height: var(--pl-toggle-thumb-size); border-radius: var(--pl-toggle-switch-radius); background: var(--pl-toggle-thumb);
  transition: left var(--pl-toggle-transition-duration);
}
.pathland-toggle input[role='switch']:checked::after { left: var(--pl-toggle-thumb-travel); }
.pathland-toggle input[role='switch']:focus-visible { outline: var(--pl-toggle-focus-ring-width) solid var(--pl-toggle-accent); outline-offset: var(--pl-toggle-focus-ring-offset); }

/* ===== Slider =====
   A renderer-owned range: the native input stays for keyboard/pointer
   interaction and accessibility, but its track, fill, and thumb are drawn from
   design tokens (`slider.track`, `slider.accent`, `slider.thumb`). The fill
   custom property is set inline by SSR and kept in sync by the DOM client. */
.pathland-slider { display: inline-flex; align-items: center; gap: var(--pl-slider-gap); }
.pathland-slider input[type='range'] {
  -webkit-appearance: none;
  appearance: none;
  flex: 1;
  min-width: 0;
  height: var(--pl-slider-height);
  margin: 0;
  background: transparent;
  cursor: pointer;
  accent-color: var(--pl-slider-accent);
  --pl-slider-fill: 0%;
}
.pathland-slider input[type='range']::-webkit-slider-runnable-track {
  height: var(--pl-slider-track-height);
  border-radius: var(--pl-slider-track-radius);
  background: linear-gradient(
    to right,
    var(--pl-slider-accent) 0%,
    var(--pl-slider-accent) var(--pl-slider-fill),
    var(--pl-slider-track) var(--pl-slider-fill),
    var(--pl-slider-track) 100%
  );
}
.pathland-slider input[type='range']::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: var(--pl-slider-thumb-size);
  height: var(--pl-slider-thumb-size);
  margin-top: var(--pl-slider-thumb-offset);
  border: var(--pl-slider-thumb-border-width) solid var(--pl-slider-track);
  border-radius: var(--pl-slider-track-radius);
  background: var(--pl-slider-thumb);
  box-shadow: var(--pl-elevation-low-x) var(--pl-elevation-low-y)
    var(--pl-elevation-low-blur) var(--pl-elevation-low-radius)
    var(--pl-elevation-low-color);
}
.pathland-slider input[type='range']::-moz-range-track {
  height: var(--pl-slider-track-height);
  border-radius: var(--pl-slider-track-radius);
  background: var(--pl-slider-track);
}
.pathland-slider input[type='range']::-moz-range-progress {
  height: var(--pl-slider-track-height);
  border-radius: var(--pl-slider-track-radius);
  background: var(--pl-slider-accent);
}
.pathland-slider input[type='range']::-moz-range-thumb {
  width: var(--pl-slider-thumb-size);
  height: var(--pl-slider-thumb-size);
  border: var(--pl-slider-thumb-border-width) solid var(--pl-slider-track);
  border-radius: var(--pl-slider-track-radius);
  background: var(--pl-slider-thumb);
  box-shadow: var(--pl-elevation-low-x) var(--pl-elevation-low-y)
    var(--pl-elevation-low-blur) var(--pl-elevation-low-radius)
    var(--pl-elevation-low-color);
}
.pathland-slider input[type='range']:focus-visible {
  outline: var(--pl-slider-focus-ring-width) solid var(--pl-slider-accent);
  outline-offset: var(--pl-slider-focus-ring-offset);
  border-radius: var(--pl-slider-track-radius);
}
.pathland-slider input[type='range']:disabled {
  cursor: default;
  opacity: var(--pl-opacity-disabled);
}

/* ===== Media (custom AudioStyle/VideoStyle) ===== */
/* A media node with custom control children wraps a bare (control-less) media
   element; the element is the app-driven playback sink, so it stays hidden and
   only the custom control children are visible. Native media (no children)
   keep their own `controls` and are not wrapped. */
.pathland-media audio,
.pathland-media video { display: none; }

/* ===== Native controls (inherit Tailwind-derived preflight + tokens) ===== */
/* Every native form control shares the design-system surface: the Tailwind
   preflight supplies the font/color reset, these tokens supply the visual base.
   App-authored inline properties (WIDTH/HEIGHT/PADDING/COLOR/…) still win. */
.pathland-control,
.pathland-input {
  border-radius: var(--pl-input-radius);
  background-color: var(--pl-input-background);
  font-family: inherit;
  font-size: var(--pl-input-font-size);
  line-height: var(--pl-control-line-height);
  color: var(--pl-input-foreground);
  outline: var(--pl-control-border-width) solid var(--pl-input-border);
  outline-offset: calc(-1 * var(--pl-control-border-width));
  transition: outline-color var(--pl-control-transition-duration), box-shadow var(--pl-control-transition-duration);
  accent-color: var(--pl-control-accent);
  color-scheme: inherit;
}
.pathland-control {
  min-height: var(--pl-control-height);
  padding: var(--pl-control-padding-vertical) var(--pl-control-padding-horizontal);
}
.pathland-input {
  display: block;
  width: 100%;
  flex: 1 1 auto;
  min-width: 0;
  padding: var(--pl-input-padding-vertical) var(--pl-input-padding-horizontal);
}
.pathland-input::placeholder,
.pathland-control::placeholder { color: var(--pl-input-placeholder); }
.pathland-input:focus,
.pathland-control:focus {
  outline: var(--pl-input-focus-ring-width) solid var(--pl-input-focus);
  outline-offset: var(--pl-input-focus-ring-offset);
}
.pathland-control:disabled { opacity: var(--pl-opacity-disabled); }

/* PICKER: keep the native dropdown affordance; theme the field + options. */
.pathland-select { display: inline-block; cursor: pointer; }
.pathland-select option {
  background-color: var(--pl-input-background);
  color: var(--pl-input-foreground);
}

/* DATE_PICKER / COLOR_PICKER: the popup itself is UA-owned; the field surface,
   scheme, and picker highlights follow the design system. */
.pathland-date,
.pathland-color { display: inline-flex; align-items: center; }
.pathland-color { padding: var(--pl-control-padding-vertical); }
.pathland-color::-webkit-color-swatch-wrapper { padding: 0; }
.pathland-color::-webkit-color-swatch {
  border: 0;
  border-radius: calc(var(--pl-input-radius) - var(--pl-input-swatch-inset));
}

/* PROGRESS_VIEW: tokenized track/fill across engines. */
.pathland-progress {
  appearance: none;
  -webkit-appearance: none;
  display: block;
  width: 100%;
  height: var(--pl-progress-height);
  border: 0;
  border-radius: var(--pl-progress-radius);
  overflow: hidden;
  background-color: var(--pl-progress-track);
  color: var(--pl-progress-fill);
  accent-color: var(--pl-progress-fill);
}
.pathland-progress::-webkit-progress-bar {
  background-color: var(--pl-progress-track);
  border-radius: var(--pl-progress-radius);
}
.pathland-progress::-webkit-progress-value {
  background-color: var(--pl-progress-fill);
  border-radius: var(--pl-progress-radius);
}
.pathland-progress::-moz-progress-bar {
  background-color: var(--pl-progress-fill);
  border-radius: var(--pl-progress-radius);
}

/* VIDEO: native controls are UA shadow DOM (best-effort scheme/accent only);
   app-driven media (`.pathland-media` + custom controls) is fully themeable. */
.pathland-video,
.pathland-media {
  max-width: 100%;
  background-color: var(--pl-color-surface);
  color: var(--pl-color-text-primary);
  border-radius: var(--pl-control-radius);
  accent-color: var(--pl-control-accent);
  color-scheme: inherit;
}

/* ===== Stepper ===== */
.pathland-stepper { display: inline-flex; align-items: center; gap: var(--pl-stepper-gap); }
.pathland-stepper button { width: var(--pl-stepper-button-size); height: var(--pl-stepper-button-size); border-radius: var(--pl-stepper-radius); border: var(--pl-stepper-border-width) solid var(--pl-stepper-border); background: var(--pl-stepper-background); color: var(--pl-stepper-accent); }

/* ===== Progress / gauge / spinner ===== */
.pathland-spinner {
  width: var(--pl-spinner-size); height: var(--pl-spinner-size); border: var(--pl-spinner-border-width) solid var(--pl-progress-track);
  border-top-color: var(--pl-progress-fill); border-radius: var(--pl-radius-full);
  animation: pathland-spin var(--pl-spinner-duration) linear infinite;
}
@keyframes pathland-spin { to { transform: rotate(360deg); } }
.pathland-gauge { display: block; height: var(--pl-gauge-height); width: 100%; background: var(--pl-gauge-track); border-radius: var(--pl-gauge-radius); overflow: hidden; }
.pathland-gauge > div { height: 100%; background: var(--pl-gauge-fill); transition: width var(--pl-gauge-transition-duration); }

/* ===== Menu (popover) ===== */
.pathland-menu { position: relative; display: inline-block; }
.pathland-menu-items {
  display: none; position: absolute; min-width: var(--pl-menu-min-width); background: var(--pl-menu-background);
  color: var(--pl-menu-foreground); border: var(--pl-menu-border-width) solid var(--pl-menu-border); border-radius: var(--pl-menu-radius);
  box-shadow: var(--pl-elevation-high-x) var(--pl-elevation-high-y) var(--pl-elevation-high-blur) var(--pl-elevation-high-radius) var(--pl-elevation-high-color);
  z-index: var(--pl-menu-z-index);
}
.pathland-menu:hover .pathland-menu-items { display: block; }

