     #[test]
     fn explicit_dark_token_ref_uses_the_forced_dark_variable() {
         let strings = string_section(&["dark.color.surface"]);
         let opcodes = vec![
             Opcode::new(category::TREE, tree::CREATE_NODE, 0, 1, component_type::TEXT as u32, 0),
             Opcode::new(
