parts.text:
Now add tests in lib.rs and capi.rs.

lib.rs test for linked mode. Add near built-in CSS tests. Test:
```rust
#[test]
fn linked_document_emits_a_cacheable_base_stylesheet_link() {
    let renderer = HtmlRenderer::new();
    let html = renderer.render_document_linked(&[], &[], 0, "/_pathland");
    let name = css::builtin_css_name();
    assert!(name.starts_with("base-") && name.ends_with(".css"));
    assert!(html.contains(&format!("<link rel=\"stylesheet\" href=\"/_pathland/{name}\">")));
    assert!(!html.contains("<style>"), "built-in CSS is not inlined");
    // token/fit styles are still allowed, but none here
    assert!(!html.contains("--pl-color-primary:"), "no inline tokens");
    // default stays inline
    let inline = renderer.render_document(&[], &[], 0);
    assert!(inline.contains("<style>"));
    assert!(inline.contains("--pl-color-primary:"));
    // empty base falls back to inline
    let empty = renderer.render_document_linked(&[], &[], 0, "");
    assert!(empty.contains("<style>"));
}
```
But `render_document_linked` with root 0 and no nodes: `render_node` returns empty. Fine.

